export const SUJETS_CCQ_2E = Object.values(LECONS).map((l) => l.sujet);
// La leçon intégrée correspondant au sujet (null si aucune ne correspond). Avec defaut = true : la leçon sur l'autonomie.
export function banqueCCQ(sujet = "", defaut = false) {
  const s = String(sujet || "").toLowerCase();
  const l = Object.values(LECONS).find((x) => x.sujet.toLowerCase() === s) || Object.values(LECONS).find((x) => x.re.test(s)) || (defaut ? LECONS.autonomie : null);
  if (!l) return null;
  return { fiche: { ...l.fiche, intro: `${l.fiche.intro} (Thème du programme de 2e secondaire : ${l.fiche.theme}.)` }, questions: l.questions };
}
export const estCCQ = (matiere) => /culture et citoyennet|citoyennet[ée] qu[ée]b/i.test(matiere || "");
